/* Public metadata discovery and authenticated administrative automation controls. */
(()=>{'use strict';
 const LX=window.LX,$=id=>document.getElementById(id),esc=v=>LX.esc(String(v??'')),db=()=>LX.cloud?.db?.(),admin=()=>LX.cloud?.isAdmin?.()===true;
 let sequence=0,rows=[],cursor=null,stack=[],term='',mediaKind='films',statusAt=0,statusBusy=false;
 const safe=v=>{try{const u=new URL(v);return u.protocol==='https:'&&!u.username&&!u.password?u.href:'';}catch{return '';}};
 function poster(row){const title=String(row.title||'LX').slice(0,90),lines=title.match(/.{1,21}(?:\s|$)|.{1,21}/g)||['LX'],hue=[...row.id].reduce((n,c)=>n+c.charCodeAt(0),0)%360;
  const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 500 750"><defs><linearGradient id="g" x2="1" y2="1"><stop stop-color="hsl(${hue} 60% 24%)"/><stop offset="1" stop-color="#080e1a"/></linearGradient></defs><rect width="500" height="750" fill="url(#g)"/><circle cx="390" cy="220" r="180" fill="none" stroke="#ffffff18"/><circle cx="390" cy="220" r="125" fill="none" stroke="#ffffff12"/><text x="34" y="59" font-size="22" fill="#b2e8ff" font-family="sans-serif" font-weight="700">LX+</text>${lines.slice(0,4).map((line,i)=>`<text x="34" y="${480+i*45}" font-size="34" fill="#f2f7ff" font-family="sans-serif" font-weight="700">${esc(line.trim())}</text>`).join('')}<text x="34" y="695" font-size="18" fill="#a9c4dd" font-family="sans-serif">${row.year||'ACERVO MUNDIAL'} · ARTE LX</text></svg>`;
  return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);
 }
 function cover(row){return safe(row.cover_url)||poster(row);}
 const mediaLabel=r=>({series:'Série',music_metadata:'Música',films:'Filme'}[r.media_kind]||'Filme');
 const card=(r,i)=>`<button type="button" class="lx41-film-card" data-lx41-film="${i}" aria-label="Informações sobre ${esc(r.title)}"><figure><img src="${esc(cover(r))}" alt="" loading="lazy" decoding="async" referrerpolicy="no-referrer"><span class="lx41-film-badge">${r.artwork?.kind==='lx'?'ARTE LX':'EM BREVE'}</span></figure><strong>${esc(r.title)}</strong><small>${r.year||'Ano não informado'} · ${mediaLabel(r)}</small></button>`;
 function heading(){return `<header class="lx41-discovery-head"><div><span class="eyebrow">LX PLUS · ACERVO MUNDIAL</span><h1>Seu universo de descobertas.</h1><p>Filmes, séries e músicas em um catálogo sempre crescendo. Os títulos sem fonte de reprodução ficam em breve.</p><nav class="lx42-discovery-tabs" aria-label="Tipo de catálogo">${[["films","Filmes"],["series","Séries"],["music_metadata","Músicas"]].map(([kind,label])=>`<button type="button" data-lx42-kind="${kind}" aria-pressed="${mediaKind===kind}">${label}</button>`).join('')}</nav></div><form id="lx41DiscoverForm" class="lx41-discovery-search"><label class="sr-only" for="lx41DiscoverQuery">Buscar neste acervo</label><input id="lx41DiscoverQuery" type="search" placeholder="Buscar neste acervo" value="${esc(term)}" maxlength="100"><button type="submit">Buscar</button></form></header>`;}
 function bind(){const root=$('homeContent');root.querySelector('#lx41DiscoverForm')?.addEventListener('submit',e=>{e.preventDefault();term=$('lx41DiscoverQuery').value.trim();cursor=null;stack=[];discover();});root.querySelectorAll('[data-lx42-kind]').forEach(b=>b.onclick=()=>{mediaKind=b.dataset.lx42Kind;cursor=null;stack=[];discover();});root.querySelectorAll('[data-lx41-film]').forEach(b=>b.onclick=()=>detail(rows[Number(b.dataset.lx41Film)]));root.querySelectorAll('img').forEach((img,i)=>img.onerror=()=>{img.onerror=null;img.src=poster(rows[i]||{id:'LX',title:'LX Cinema'});});}
 async function discover(){const token=++sequence,root=$('homeContent');if(!root)return;$('hero').classList.add('hidden');$('welcome').classList.add('hidden');root.innerHTML=`<section class="lx41-discovery">${heading()}<div class="lx41-empty" role="status">Buscando o acervo…</div></section>`;bind();
  try{if(!db())throw new Error('offline');const {data,error}=await db().rpc('lx_discover_catalog',{p_kind:mediaKind,p_query:term,p_before:cursor,p_limit:36});if(error)throw error;if(token!==sequence||LX.state.category!=='Acervo mundial')return;
   rows=data?.items||[];root.innerHTML=`<section class="lx41-discovery">${heading()}<div class="lx41-discovery-grid">${rows.map(card).join('')}</div>${rows.length?'':`<div class="lx41-empty"><h2>${term?'Nenhum título encontrado.':'As primeiras descobertas estão chegando.'}</h2><p>${term?'Tente buscar pelo título original ou por outra palavra.':'A busca automática acrescenta fichas ao acervo todos os dias.'}</p></div>`}<footer class="lx41-discovery-footer"><p>Dados: Wikidata · CC0. Imagens livres com créditos na ficha. As capas “Arte LX” foram criadas para organizar o acervo.</p><div class="lx41-discovery-pages">${stack.length?'<button class="lx41-page-button" data-lx41-prev>← Anterior</button>':''}${data?.has_more?'<button class="lx41-page-button" data-lx41-next>Próxima →</button>':''}</div></footer></section>`;bind();
   root.querySelector('[data-lx41-next]')?.addEventListener('click',()=>{stack.push(cursor);cursor=rows.at(-1)?.id||null;discover();window.scrollTo({top:0,behavior:'smooth'});});root.querySelector('[data-lx41-prev]')?.addEventListener('click',()=>{cursor=stack.pop()||null;discover();});
  }catch{if(token!==sequence)return;root.innerHTML=`<section class="lx41-discovery">${heading()}<div class="lx41-empty" role="alert"><h2>O acervo não carregou.</h2><p>Confira sua conexão e tente novamente.</p><button class="lx41-page-button" id="lx41DiscoverRetry">Tentar novamente</button></div></section>`;bind();$('lx41DiscoverRetry').onclick=discover;}
 }
 function detail(row){if(!row)return;const art=row.artwork||{},source=safe(row.source_url),credit=safe(art.source_url);
  $('modal').innerHTML=`<button class="close-btn" type="button" aria-label="Fechar" onclick="LX.ui.close()">×</button><article class="lx41-film-detail"><img src="${esc(cover(row))}" alt="Capa de ${esc(row.title)}"><div><span class="eyebrow">ACERVO MUNDIAL · ${row.year||'CINEMA'}</span><h2>${esc(row.title)}</h2><p>${esc(row.description||'Filme catalogado no acervo mundial da LX Plus.')}</p><p class="lx41-info-note">Em breve na LX Plus. Esta é uma ficha de descoberta. A reprodução é publicada na área Assistir após a verificação da fonte e da autorização.</p>${source?`<a href="${esc(source)}" target="_blank" rel="noopener noreferrer">Dados e referências ↗</a>`:''}<small>${art.kind==='lx'?'Arte de capa criada pela LX Plus.':`${esc(art.creator||'')} · ${esc(art.license||art.credit||'Capa do catálogo')}`}${credit?` · <a href="${esc(credit)}" target="_blank" rel="noopener noreferrer">Créditos da imagem ↗</a>`:''}</small>${admin()?`<form id="lx41CoverEditor" class="lx41-cover-editor"><label>Título<input id="lx41CoverTitle" value="${esc(row.title)}" required maxlength="500"></label><label>Capa HTTPS<input id="lx41CoverURL" type="url" value="${esc(safe(row.cover_url))}" placeholder="https://…" required></label><button class="lx41-page-button" type="submit">Salvar capa</button></form>`:''}</div></article>`;$('overlay').classList.remove('hidden');
  $('lx41CoverEditor')?.addEventListener('submit',async e=>{e.preventDefault();const cover=safe($('lx41CoverURL').value),title=$('lx41CoverTitle').value.trim();if(!cover||!title)return LX.toast('Informe um título e uma capa HTTPS.');const button=e.target.querySelector('button');button.disabled=true;try{const {error,data}=await db().rpc('lx_auto_edit_discovery',{p_id:row.id,p_title:title,p_cover_url:cover});if(error||!data)throw error;Object.assign(row,{title,cover_url:cover,artwork:{kind:'admin',credit:'Capa editada pelo ADM'}});detail(row);LX.toast('Capa salva.');}catch{LX.toast('Não foi possível salvar.');}finally{button.disabled=false;}});
 }
 function addNavigation(){const nav=$('categoryNav');if(!nav||LX.state.mode!=='Assistir'||nav.querySelector('[data-lx41-discover]'))return;const button=document.createElement('button');button.type='button';button.dataset.lx41Discover='';button.textContent='Acervo mundial';button.classList.toggle('active',LX.state.category==='Acervo mundial');button.onclick=()=>{LX.state.category='Acervo mundial';LX.state.query='';$('searchInput').value='';cursor=null;stack=[];term='';LX.ui.renderApp();};nav.appendChild(button);}
 const oldRender=LX.ui.renderApp;LX.ui.renderApp=function(...args){if(LX.state.mode==='Assistir'&&LX.state.category==='Acervo mundial'){$('app').classList.remove('lx-music-mode','lx-uc-searching');if(LX.state.query&&term!==LX.state.query){term=LX.state.query;cursor=null;stack=[];}LX.ui.renderCategories();addNavigation();discover();return;}sequence++;$('hero').classList.remove('hidden');$('welcome').classList.remove('hidden');const value=oldRender.apply(this,args);addNavigation();const music=document.querySelector('.lx-music-side')||document.querySelector('.lx-music-main');if(LX.state.mode==='Ouvir'&&music&&!music.querySelector('[data-lx42-music-discover]')){const b=document.createElement('button');b.className='lx42-music-discover';b.dataset.lx42MusicDiscover='';b.textContent='Acervo mundial · Em breve ↗';b.onclick=()=>{mediaKind='music_metadata';LX.state.mode='Assistir';LX.state.category='Acervo mundial';cursor=null;stack=[];term='';LX.ui.renderApp();};music.prepend(b);}return value;};
 const jobTime=value=>new Date(value).toLocaleString('pt-BR',{timeZone:'America/Fortaleza'});
 const number=value=>Number.isFinite(Number(value))?Math.max(0,Number(value)):0;
 const day=value=>{const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Fortaleza',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(value));const get=key=>parts.find(p=>p.type===key).value;return get('year')+'-'+get('month')+'-'+get('day');};
 const midnight=value=>Date.parse(day(value)+'T00:00:00-03:00')+86400000;
 const schedule=(kind,after,inclusive=false)=>{const offset=kind==='music'?420000:0;return Math.ceil((after+(inclusive?0:1)-offset)/900000)*900000+offset;};
 function jobState(j,now=Date.now()){
  const today=!j.day||j.day===day(now),countLimit=today&&number(j.daily_limit)>0&&number(j.processed)>=number(j.daily_limit);
  const daily=today&&(j.last_error==='DAILY_AUDIO_BUDGET'||j.status==='daily_limit'||countLimit),space=j.last_error==='ASSET_STORAGE_BUDGET';
  const future=Number(new Date(j.next_run_at||0))>now,retry=!!j.last_error&&!['DAILY_AUDIO_BUDGET','ASSET_STORAGE_BUDGET'].includes(j.last_error);
  const label=j.enabled===false?'Pausada':j.status==='running'?'Em execução':daily?(j.kind!=='music'?'Meta diária concluída':'Pausa diária'):space?'Aguardando espaço':future||retry?'Aguardando nova tentativa':'Aguardando próxima busca';
  let after=Math.max(now,Number(new Date(j.next_run_at||0))||0);if(daily)after=Math.max(after,midnight(now));
  const next=schedule(j.kind,after,after>now);
  return {label,today,daily,space,retry,next,disabled:j.enabled===false||j.status==='running'||daily||future};
 }
 const runResult=r=>({DAILY_AUDIO_BUDGET:'Pausa diária',ASSET_STORAGE_BUDGET:'Aguardando espaço'}[r.error_code]||(r.error_code?'Nova tentativa':{success:'Concluída',running:'Em execução',retry:'Nova tentativa',expired:'Reagendada'}[r.status]||'Aguardando'));
 function jobCard(j){
  const s=jobState(j),films=j.kind!=='music',name=({films:'Filmes e capas',series:'Séries e capas',music_metadata:'Catálogo musical',music:'Músicas em MP3'}[j.kind]||'Rotina'),limit=number(j.daily_limit),done=number(j.processed),percent=limit?Math.min(100,Math.round(done/limit*100)):0;
  const note=s.daily?'A rotina retoma automaticamente no próximo dia.':s.space?'A reserva de hospedagem foi atingida. A rotina aguarda espaço disponível.':s.retry?'A fonte será consultada novamente no horário indicado.':'As novidades são publicadas após a verificação da fonte.';
  const caption=(films?'fichas adicionadas':'MP3 publicados')+(s.today?' hoje':' no último dia computado');
  return '<article class="lx41-auto-job" data-lx41-job="'+esc(j.kind)+'"><div class="lx41-auto-job-title"><h3>'+name+'</h3><span class="lx41-auto-mode">'+(j.enabled===false?'Pausada':'Automática')+'</span></div><span class="lx41-auto-status '+(s.retry?'retry':'')+'">'+esc(s.label)+'</span><strong>'+number(j.published).toLocaleString('pt-BR')+'<small>'+caption+'</small></strong><div class="lx41-auto-progress" role="progressbar" aria-label="Registros conferidos" aria-valuemin="0" aria-valuemax="'+limit+'" aria-valuenow="'+Math.min(done,limit)+'"><i style="width:'+percent+'%"></i></div><small>'+done.toLocaleString('pt-BR')+' de '+limit.toLocaleString('pt-BR')+' registros conferidos<br>'+(films?'Busca programada a cada 15 minutos.':'Áudio transferido: '+(number(j.bytes)/1000000).toFixed(1)+' de '+(number(j.daily_budget_bytes||150000000)/1000000).toFixed(0)+' MB/dia.')+'<br>'+(j.last_run_at?'Última execução: '+esc(jobTime(j.last_run_at)):'Primeira execução agendada')+'<br>'+esc(note)+(j.enabled!==false&&j.status!=='running'?'<br><b>Próxima busca prevista: '+esc(jobTime(s.next))+'</b>':'')+'</small><button type="button" data-lx41-run="'+esc(j.kind)+'" '+(s.disabled?'disabled':'')+'>Executar agora</button></article>';
 }
 let statusSignature='',lastData=null;
 const names={films:'Filmes',series:'Séries',music_metadata:'Catálogo musical',music:'MP3'};
 function chart(history=[]){const today=day(Date.now()),dates=Array.from({length:14},(_,i)=>day(Date.parse(today+'T12:00:00-03:00')-(13-i)*86400000));const max=Math.max(1,...dates.map(date=>history.filter(r=>r.day===date).reduce((n,r)=>n+number(r.added),0)));return '<section class="lx42-history"><h3>Novidades por dia</h3><p>Últimos 14 dias · fichas adicionadas e MP3 publicados · horário de Fortaleza</p><div class="lx42-chart" role="img" aria-label="Adições diárias ao catálogo">'+dates.map(date=>{const rows=history.filter(r=>r.day===date),total=rows.reduce((n,r)=>n+number(r.added),0);return '<div class="lx42-chart-day" title="'+esc(date)+' · '+total+' adições"><strong>'+total+'</strong><div class="lx42-chart-stack">'+Object.keys(names).map(kind=>'<i class="lx42-bar-'+kind+'" style="height:'+Math.round(number(rows.find(r=>r.kind===kind)?.added)/max*140)+'px"></i>').join('')+'</div><small>'+date.slice(8)+'/'+date.slice(5,7)+'</small></div>';}).join('')+'</div><div class="lx42-chart-key">'+Object.entries(names).map(([kind,label])=>'<span class="lx42-key-'+kind+'">'+label+'</span>').join('')+'</div></section>';}

 function latest(items){return '<section class="lx41-auto-latest"><h3>Últimas publicações</h3>'+(items.length?'<ul>'+items.map(r=>{const p=r.payload||{},image=safe(p.cover);return '<li>'+(image?'<img src="'+esc(image)+'" alt="" loading="lazy" referrerpolicy="no-referrer">':'<span class="lx41-auto-art" aria-hidden="true">'+(p.type==='Música'?'♫':'▣')+'</span>')+'<div><strong>'+esc(p.title||'Conteúdo LX')+'</strong><small>'+esc(p.type||'Conteúdo')+' · '+esc(jobTime(r.updated_at))+'</small></div><span class="lx41-auto-published">Publicado</span></li>';}).join('')+'</ul>':'<p>As primeiras publicações verificadas aparecerão aqui.</p>')+'</section>';}
 function body(data,items){return '<div class="lx41-auto-summary"><div><strong>'+number(data.discovery_total).toLocaleString('pt-BR')+'</strong><span>fichas no acervo mundial</span></div><div><strong>'+number(data.native_auto_total).toLocaleString('pt-BR')+'</strong><span>mídias publicadas automaticamente</span></div><div><strong>'+(number(data.asset_bytes)/1000000).toFixed(1)+' MB</strong><span>capas, livros e áudios hospedados</span></div></div><div class="lx41-auto-jobs">'+(data.jobs||[]).map(jobCard).join('')+'</div>'+chart(data.daily_history)+latest(items)+'<h3>Atividade das rotinas</h3><div class="lx41-auto-table-wrap"><table class="lx41-auto-runs"><thead><tr><th>Rotina</th><th>Última execução</th><th>Adições</th><th>Estado</th></tr></thead><tbody>'+(data.runs||[]).map(r=>'<tr><td>'+esc(names[r.kind]||'Rotina')+'</td><td>'+esc(jobTime(r.started_at))+'</td><td>'+number(r.added)+(r.kind==='music'?' MP3':' fichas')+' · '+number(r.playable)+' mídias</td><td>'+esc(runResult(r))+'</td></tr>').join('')+'</tbody></table></div><p>As rotinas continuam no servidor com o navegador fechado. Filmes, séries e catálogo musical têm limites independentes. Filmes: até 2.000 fichas por dia. Músicas: arquivos autorizados, verificados e hospedados no player LX. O limite diário renova à meia-noite de Fortaleza; edições do ADM são preservadas.</p>';}
 function connection(root,connected,message){const badge=root.querySelector('[data-lx41-live]');if(badge){badge.dataset.connected=String(connected);badge.textContent=message;}root.querySelector('[data-lx41-checked]').textContent=connected?'Conferido às '+new Date().toLocaleTimeString('pt-BR',{timeZone:'America/Fortaleza'}):'Últimos dados preservados. Tente atualizar novamente.';}
 async function mountAdmin(force=false){
  const main=$('adminMain');if(!admin()||LX.state.screen!=='admin'||!main)return;
  if(LX.state.adminPage==='settings'){if(!main.querySelector('[data-lx41-auto-shortcut]')){const shortcut=document.createElement('section');shortcut.className='lx41-auto-panel';shortcut.dataset.lx41AutoShortcut='';shortcut.innerHTML='<h2>Automação</h2><p>Acompanhe as rotinas, os limites, os horários de retomada e as últimas publicações.</p><button type="button" class="lx41-page-button">Abrir Automação ↗</button>';shortcut.querySelector('button').onclick=()=>LX.admin.render('automation');main.appendChild(shortcut);}return;}
  if(LX.state.adminPage!=='automation')return;
  let root=main.querySelector('[data-lx41-auto-panel]');
  if(!root){root=document.createElement('section');root.className='lx41-auto-panel';root.dataset.lx41AutoPanel='';root.innerHTML='<div class="lx41-auto-head"><div><h2>Sistemas automáticos</h2><span class="lx41-auto-live" data-lx41-live data-connected="false" role="status">Conectando…</span><small data-lx41-checked>Atualização da tela a cada 10 segundos.</small></div><button type="button" class="lx41-page-button" data-lx41-refresh>Atualizar agora</button></div><div data-lx41-auto-body><p role="status">Carregando as rotinas…</p></div>';main.appendChild(root);root.querySelector('[data-lx41-refresh]').onclick=()=>mountAdmin(true);statusAt=0;statusSignature='';lastData=null;}
  if(statusBusy||document.hidden||(!force&&Date.now()-statusAt<10000)||!db())return;
  if(!navigator.onLine){connection(root,false,'Sem conexão');return;}
  statusBusy=true;statusAt=Date.now();const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000),attach=p=>typeof p.abortSignal==='function'?p.abortSignal(controller.signal):p;
  try{
   const query=db().from('lx_catalog').select('id,payload,published,updated_at').eq('published',true).contains('payload',{autoPublished:true}).order('updated_at',{ascending:false}).limit(8);
   const [status,publications]=await Promise.all([attach(db().rpc('lx_auto_status')),attach(query)]);
   if(status.error||publications.error)throw status.error||publications.error;
   if(!root.isConnected||LX.state.adminPage!=='automation')return;
   const data=status.data||{},items=publications.data||[],signature=JSON.stringify([data,items,day(Date.now()),(data.jobs||[]).map(j=>jobState(j))]);
   if(signature!==statusSignature){const scroll=root.querySelector('.lx41-auto-table-wrap')?.scrollLeft||0,focused=document.activeElement?.dataset.lx41Run;root.querySelector('[data-lx41-auto-body]').innerHTML=body(data,items);statusSignature=signature;lastData=data;root.querySelector('.lx41-auto-table-wrap').scrollLeft=scroll;if(focused)root.querySelector('[data-lx41-run="'+focused+'"]')?.focus();}
   connection(root,true,'Ao vivo · atualiza a cada 10 s');
   root.querySelectorAll('[data-lx41-run]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{const r=await db().rpc('lx_auto_run_now',{p_kind:button.dataset.lx41Run});if(r.error)throw r.error;LX.toast(r.data?'Execução agendada.':'A rotina está em execução ou aguarda o horário de retomada.');}catch{LX.toast('Não foi possível agendar.');}statusAt=0;setTimeout(()=>mountAdmin(true),1500);});
  }catch{if(root.isConnected){connection(root,false,'Atualização indisponível');if(!lastData)root.querySelector('[data-lx41-auto-body]').innerHTML='<p role="alert">Não foi possível carregar as rotinas. Use Atualizar agora para tentar novamente.</p>';}}finally{clearTimeout(timer);statusBusy=false;}
 }
 function renderAutomation(){
  const settings=document.querySelector('#adminNav [data-admin="settings"]');if(!admin()||settings?.disabled)return LX.toast('Seu cargo não possui acesso à automação.');
  LX.state.adminPage='automation';document.querySelectorAll('#adminNav [data-admin]').forEach(b=>b.classList.toggle('active',b.dataset.admin==='automation'));
  $('adminMain').innerHTML='<header class="admin-head"><div><span class="eyebrow">LX ADMIN · OPERAÇÃO</span><h1>Automação</h1><p>Saiba o que está buscando, o que foi publicado e quando cada sistema volta a executar.</p></div></header>';
  statusAt=0;return mountAdmin(true);
 }
 const oldAdminRender=LX.admin.render;LX.admin.render=function(page,...args){if(page==='automation')return renderAutomation();const result=oldAdminRender.call(this,page,...args);mountAdmin();return result;};
 LX.autoCatalog={discover,detail,mountAdmin,refresh:()=>mountAdmin(true),jobState};addNavigation();setInterval(mountAdmin,5000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)mountAdmin(true);});window.addEventListener('online',()=>mountAdmin(true));
})();
